    background: rgba(255,255,255,0.02);
    border-left: 2px solid #333;
    padding: 20px;
    margin-bottom: 20px;
}

.sub-section h3 {
    font-family: 'Outfit', sans-serif;
    font-size: 15px;
    color: #e0e0e0;
    margin-top: 0;
    margin-bottom: 10px;
    text-transform: uppercase;
}

/* LISTY */
.legal-list { padding-left: 20px; margin-bottom: 20px; }
.legal-list li {
    color: #999; margin-bottom: 8px; list-style-type: none; font-size: 14px; position: relative;
}
.legal-list li::before {
    content: '›'; color: #C5A059; position: absolute; left: -20px; font-weight: bold;
}

/* STOPKA */
.legal-footer {
    text-align: center; font-size: 12px; color: #444; margin-top: 40px; text-transform: uppercase; letter-spacing: 1px;
}

